const icons={overview:'M3 3h7v7H3V3m11 0h7v7h-7V3M3 14h7v7H3v-7m11 0h7v7h-7v-7',mine:'M8 9a4 4 0 1 0 8 0 4 4 0 0 0-8 0M4 21a8 8 0 0 1 16 0',team:'M4 4h16v13H9l-5 4V4m4 5h8m-8 4h5',plan:'M4 4v16l8-4 8 4V4l-8 4-8-4m8 4v9',watch:'M21 12a9 9 0 1 1-3-7M12 7v5l3 2m3-12v4h-4',book:'M6 3h12v18l-3-2-3 2-3-2-3 2Zm3 5h6m-6 4h6',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',link:'m9 15 6-6M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0m2 0 2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0',plane:'m3 9 8 2V3l3 2v7l6 3v2l-6-1v4l-3 1v-6l-8-3Z'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.check}"/></svg>`;
const btn=(label,action,cls='',disabled=false,extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
const field=(label,name,value,type='text',attrs='')=>`<label class="field"><span>${esc(label)}</span><input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,value,options)=>`<label class="field"><span>${esc(label)}</span><select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></label>`;
